function requireScope(scope: string) {
  return (req: Request, res: Response, next: NextFunction) => {
    const scopes: string[] = (req as any).auth?.scopes ?? [];
    if (!scopes.includes(scope)) {
      res.status(403).json({ error: `missing scope ${scope}` });
      return;
    }
    next();
  };
}

